const j = $input.first().json || {};
const telegram_id = String(j.telegram_id == null ? '' : j.telegram_id).trim();
let payload = {};
const raw = j.payload_json;
if (raw && typeof raw === 'object') payload = raw;
else if (raw && String(raw).trim()) { try { payload = JSON.parse(String(raw)) || {}; } catch (e) { payload = {}; } }
return [{ json: {
  has_id: telegram_id.length > 0,
  action: String(j.action || '').trim().toUpperCase(),
  telegram_id,
  chat_id: String(j.chat_id || telegram_id).trim(),
  text: String(j.text == null ? '' : j.text).trim(),
  update_id: String(j.update_id || ''),
  payload,
} }];

function uuidv4() { const h = '0123456789abcdef'; let s = ''; for (let i = 0; i < 36; i++) { if (i === 8 || i === 13 || i === 18 || i === 23) { s += '-'; continue; } if (i === 14) { s += '4'; continue; } let r = Math.floor(Math.random() * 16); if (i === 19) r = (r & 3) | 8; s += h[r]; } return s; }
const inp = $('Normalize Input').first().json;
function rows(name, key) { return $(name).all().map(function (i) { return i.json; }).filter(function (r) { return r && r[key]; }); }
const S = {};
rows('Get Settings', 'setting_key').forEach(function (r) { S[r.setting_key] = r.setting_value; });
function parseIds(v) {
  try { const a = JSON.parse(v || '[]'); if (Array.isArray(a)) return a.map(function (x) { return String(x).trim(); }).filter(Boolean); } catch (e) {}
  return String(v || '').split(/[\s,;]+/).map(function (s) { return s.trim(); }).filter(Boolean);
}
const admins = parseIds(S.admin_telegram_ids);
const isAdmin = admins.indexOf(inp.telegram_id) >= 0;
const tz = S.timezone || 'Asia/Almaty';
const now = DateTime.now().setZone(tz);
const nowIso = now.toISO();
const MAX = Number(S.max_fish_coins) || 100;
const employees = rows('Get Employees', 'employee_id');
const activeEmps = employees.filter(function (r) { return String(r.employee_status).toUpperCase() === 'ACTIVE'; });
const me = activeEmps.find(function (r) { return String(r.telegram_id) === inp.telegram_id; });
const dlg = rows('Get Dialog', 'telegram_id')[0];
let dlgPayload = {};
if (dlg) { try { dlgPayload = JSON.parse(dlg.payload_json || '{}') || {}; } catch (e) { dlgPayload = {}; } }
const txs = me ? rows('Get My Transactions', 'transaction_id').filter(function (r) { return r.employee_id === me.employee_id && r.tx_status !== 'DUPLICATE_ROLLBACK'; }) : [];
const shifts = rows('Get My Shifts', 'shift_id');
const pending = rows('Get Pending Requests', 'request_id').filter(function (r) { return r.status === 'PENDING'; });

const MENU = [['🟢 Начать работу', '🔴 Завершить работу'], ['🐟 Fish Coins', '📊 Моя статистика'], ['🏖 Отпуск', '🤒 Больничный'], ['📅 Встреча', '👤 Мой профиль'], ['🤖 Спросить TUNA']];
if (isAdmin) MENU.push(['⚙️ Админ-панель']);
const ADMIN_KB = [['📋 Заявки на рассмотрении', '👥 Сотрудники'], ['🏠 Главное меню']];
const CANCEL_BTN = '❌ Отмена';
const SKIP_BTN = 'Пропустить';
const YES_BTN = '✅ Да, выполнить';
const NO_BTN = '❌ Нет, отменить';
const CANCEL_KB = [[CANCEL_BTN]];
const SKIP_KB = [[SKIP_BTN], [CANCEL_BTN]];
const CONFIRM_KB = [[YES_BTN], [NO_BTN]];
const TYPE_LABEL = { VACATION: 'Отпуск', SICK_LEAVE: 'Больничный', MEETING: 'Встреча' };
const TX_LABEL = { WELCOME_BONUS: 'Приветственный бонус', SHIFT_BONUS: 'За смену', ACHIEVEMENT: 'Достижение', ADMIN_CREDIT: 'Начисление админом', ADMIN_DEBIT: 'Списание админом' };

function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const R = { op: 'REPLY_ONLY', result: 'OK', reply: null, dialog: null, request: null, request_update: null, ledger: null, ledger_target_telegram: null, geo: [], reset: null, audit: null, notifications: [] };
function reply(text, kbType, kb) {
  R.reply = { action: 'REPLY', chat_id: inp.chat_id, text: text, keyboard_type: kbType, keyboard: kb || (kbType === 'main_menu' ? MENU : []) };
}
function done() { return [{ json: Object.assign({ telegram_id: inp.telegram_id, now_iso: nowIso, is_admin: isAdmin }, R) }]; }
function setDialog(flow, step, payload, minutes) {
  R.op = 'SET_DIALOG';
  R.dialog = { flow: flow, step: step, payload_json: JSON.stringify(payload || {}), expires_at: now.plus({ minutes: minutes }).toISO() };
}
function parseDate(s) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})$/.exec(String(s || '').trim());
  if (!m) return null;
  const dt = DateTime.fromObject({ year: Number(m[3]), month: Number(m[2]), day: Number(m[1]) }, { zone: tz });
  return dt.isValid ? dt : null;
}
function parseDateTime(s) {
  const m = /^(\d{2})\.(\d{2})\.(\d{4})\s+([01]\d|2[0-3]):([0-5]\d)$/.exec(String(s || '').trim());
  if (!m) return null;
  const dt = DateTime.fromObject({ year: Number(m[3]), month: Number(m[2]), day: Number(m[1]), hour: Number(m[4]), minute: Number(m[5]) }, { zone: tz });
  return dt.isValid ? dt : null;
}
function fmtTs(iso) { const d = DateTime.fromISO(String(iso || '')); return d.isValid ? d.setZone(tz).toFormat('dd.MM.yyyy HH:mm') : String(iso || ''); }
function fmtMin(m) { m = Math.round(m || 0); return Math.floor(m / 60) + ' ч ' + (m % 60) + ' мин'; }

// ---------- command parsing ----------
function parseCommand(t) {
  const s = String(t || '').trim();
  if (s === '⚙️ Админ-панель' || s === '/admin') return { action: 'ADMIN_MENU', args: {} };
  if (s === '📋 Заявки на рассмотрении' || s === '/pending') return { action: 'LIST_PENDING', args: {} };
  if (s === '👥 Сотрудники' || s === '/employees') return { action: 'LIST_EMPLOYEES', args: {} };
  const parts = s.split(/\s+/);
  const cmd = (parts[0] || '').toLowerCase();
  if (cmd === '/approve' || cmd === '/reject') return { action: cmd === '/approve' ? 'APPROVE_REQUEST' : 'REJECT_REQUEST', args: { request_id: parts[1] || '', comment: parts.slice(2).join(' ') } };
  if (cmd === '/coins') return { action: 'ADJUST_COINS', args: { tuna_id: parts[1] || '', amount: parts[2] || '', reason: parts.slice(3).join(' ') } };
  if (cmd === '/achieve') return { action: 'GRANT_ACHIEVEMENT', args: { tuna_id: parts[1] || '', rule_id: parts[2] || '' } };
  if (cmd === '/geo') return { action: 'SET_GEO', args: { lat: parts[1] || '', lon: parts[2] || '', radius: parts[3] || '' } };
  if (cmd === '/reset') return { action: 'RESET_PROFILE', args: { tuna_id: parts[1] || '' } };
  return null;
}

let action = inp.action;
let params = {};
if (action === 'ADMIN_COMMAND') {
  const pc = parseCommand(inp.text);
  if (pc) { action = pc.action; params = pc.args; } else action = 'UNKNOWN';
} else {
  const pc = parseCommand(inp.text);
  if (pc && pc.action === action) params = pc.args;
}
params = Object.assign({}, params, inp.payload || {});

// ---------- HR dialogs ----------
const HR_FLOWS = { VACATION: { type: 'VACATION', first: 'START_DATE' }, SICK: { type: 'SICK_LEAVE', first: 'START_DATE' }, MEETING: { type: 'MEETING', first: 'DATETIME' } };
function hrPrompt(flow, step) {
  if (flow === 'VACATION') {
    if (step === 'START_DATE') return { text: '🏖 Заявка на отпуск.\nВведите дату начала в формате ДД.ММ.ГГГГ.', kb: CANCEL_KB };
    if (step === 'END_DATE') return { text: 'Введите дату окончания отпуска (ДД.ММ.ГГГГ).', kb: CANCEL_KB };
    return { text: 'Добавьте комментарий (необязательно) или нажмите «Пропустить».', kb: SKIP_KB };
  }
  if (flow === 'SICK') {
    if (step === 'START_DATE') return { text: '🤒 Больничный.\nВведите дату начала в формате ДД.ММ.ГГГГ. Диагноз указывать не нужно.', kb: CANCEL_KB };
    if (step === 'END_DATE') return { text: 'Ожидаемая дата окончания (ДД.ММ.ГГГГ) — или «Пропустить», если пока неизвестно.', kb: SKIP_KB };
    return { text: 'Комментарий (необязательно). Пожалуйста, не указывайте диагноз — он не нужен.', kb: SKIP_KB };
  }
  if (step === 'DATETIME') return { text: '📅 Запрос встречи.\nВведите желаемые дату и время в формате ДД.ММ.ГГГГ ЧЧ:ММ (например, 20.10.2026 15:00).', kb: CANCEL_KB };
  return { text: 'Кратко опишите тему встречи.', kb: CANCEL_KB };
}
function hrHandle(flow, step, t, p) {
  const today = now.startOf('day');
  if (flow === 'VACATION') {
    if (step === 'START_DATE') {
      const d = parseDate(t);
      if (!d) return { error: 'Такой даты нет или формат неверный (нужно ДД.ММ.ГГГГ).' };
      if (d < today) return { error: 'Дата начала отпуска не может быть в прошлом.' };
      if (d > today.plus({ days: 365 })) return { error: 'Дата начала — не позднее чем через год.' };
      p.start_date = d.toFormat('dd.MM.yyyy'); return { next: 'END_DATE' };
    }
    if (step === 'END_DATE') {
      const d = parseDate(t); const s = parseDate(p.start_date);
      if (!d) return { error: 'Такой даты нет или формат неверный (нужно ДД.ММ.ГГГГ).' };
      if (d < s) return { error: 'Дата окончания раньше даты начала.' };
      if (d > s.plus({ days: 60 })) return { error: 'Отпуск не может быть длиннее 60 дней в одной заявке.' };
      p.end_date = d.toFormat('dd.MM.yyyy'); return { next: 'COMMENT' };
    }
    if (t !== SKIP_BTN && t.length > 300) return { error: 'Комментарий не длиннее 300 символов.' };
    p.comment = t === SKIP_BTN ? '' : t; return { submit: true };
  }
  if (flow === 'SICK') {
    if (step === 'START_DATE') {
      const d = parseDate(t);
      if (!d) return { error: 'Такой даты нет или формат неверный (нужно ДД.ММ.ГГГГ).' };
      if (d < today.minus({ days: 30 }) || d > today.plus({ days: 7 })) return { error: 'Дата начала — от 30 дней назад до 7 дней вперёд.' };
      p.start_date = d.toFormat('dd.MM.yyyy'); return { next: 'END_DATE' };
    }
    if (step === 'END_DATE') {
      if (t === SKIP_BTN) { p.end_date = ''; return { next: 'COMMENT' }; }
      const d = parseDate(t); const s = parseDate(p.start_date);
      if (!d) return { error: 'Такой даты нет или формат неверный (нужно ДД.ММ.ГГГГ), либо нажмите «Пропустить».' };
      if (d < s) return { error: 'Дата окончания раньше даты начала.' };
      if (d > s.plus({ days: 60 })) return { error: 'Срок не более 60 дней в одной заявке.' };
      p.end_date = d.toFormat('dd.MM.yyyy'); return { next: 'COMMENT' };
    }
    if (t !== SKIP_BTN && t.length > 300) return { error: 'Комментарий не длиннее 300 символов.' };
    p.comment = t === SKIP_BTN ? '' : t; return { submit: true };
  }
  if (step === 'DATETIME') {
    const d = parseDateTime(t);
    if (!d) return { error: 'Нужен формат ДД.ММ.ГГГГ ЧЧ:ММ.' };
    if (d < now) return { error: 'Время встречи должно быть в будущем.' };
    if (d > now.plus({ days: 60 })) return { error: 'Встречу можно запросить не дальше чем на 60 дней вперёд.' };
    p.start_date = d.toFormat('dd.MM.yyyy HH:mm'); p.end_date = ''; return { next: 'TOPIC' };
  }
  if (t.length < 3 || t.length > 300) return { error: 'Тема — от 3 до 300 символов.' };
  p.comment = t; return { submit: true };
}

// ---------- admin operations ----------
function findEmp(tunaId) {
  const id = String(tunaId || '').trim().toUpperCase();
  return activeEmps.find(function (r) { return String(r.tuna_id).toUpperCase() === id; });
}
function validateOp(op, p, nonce) {
  if (op === 'APPROVE_REQUEST' || op === 'REJECT_REQUEST') {
    const rid = String(p.request_id || '').trim().toUpperCase();
    if (!rid) return { error: 'Укажите номер заявки: /approve REQ-XXXXXX [комментарий]' };
    const req = pending.find(function (r) { return String(r.request_id).toUpperCase() === rid; });
    if (!req) return { error: 'Заявка ' + esc(rid) + ' не найдена или уже рассмотрена.' };
    const emp = employees.find(function (e) { return e.employee_id === req.employee_id; }) || {};
    const status = op === 'APPROVE_REQUEST' ? 'APPROVED' : 'REJECTED';
    const word = status === 'APPROVED' ? 'одобрена ✅' : 'отклонена ❌';
    const cmt = String(p.comment || '').trim().slice(0, 300);
    const period = req.start_date + (req.end_date ? ' — ' + req.end_date : '');
    return {
      summary: (status === 'APPROVED' ? 'Одобрить' : 'Отклонить') + ' заявку ' + req.request_id + ' (' + (TYPE_LABEL[req.request_type] || req.request_type) + ', ' + esc(emp.full_name || req.telegram_id) + ', ' + period + ')' + (cmt ? '\nКомментарий: ' + esc(cmt) : ''),
      exec: {
        op: 'DECIDE_REQUEST',
        request_update: { request_id: req.request_id, status: status, reviewed_at: nowIso, reviewed_by: inp.telegram_id, comment: (req.comment || '') + (cmt ? (req.comment ? ' | ' : '') + 'Админ: ' + cmt : '') },
        audit: { action: op, target_employee_id: req.employee_id, details: { request_id: req.request_id, before: 'PENDING', after: status, comment: cmt } },
        notifications: [{ chat_id: req.telegram_id, text: 'Ваша заявка ' + req.request_id + ' (' + (TYPE_LABEL[req.request_type] || req.request_type) + ', ' + period + ') ' + word + '.' + (cmt ? '\nКомментарий: ' + esc(cmt) : '') }],
      },
    };
  }
  if (op === 'ADJUST_COINS' || op === 'GRANT_ACHIEVEMENT') {
    const emp = findEmp(p.tuna_id);
    if (!emp) return { error: 'Активный сотрудник ' + esc(p.tuna_id || '') + ' не найден. Формат: /coins TUNA-000001 +5 причина' };
    const bal = Number(emp.fish_coins_balance) || 0;
    let amount; let type; let reason; let key;
    if (op === 'ADJUST_COINS') {
      amount = parseInt(String(p.amount || '').replace(/\s/g, ''), 10);
      if (!Number.isFinite(amount) || amount === 0 || Math.abs(amount) > MAX) return { error: 'Сумма — целое число от -' + MAX + ' до +' + MAX + ', не 0.' };
      reason = String(p.reason || '').trim();
      if (reason.length < 3) return { error: 'Укажите причину (минимум 3 символа).' };
      if (amount > 0 && bal + amount > MAX) return { error: 'Начисление превысит максимум ' + MAX + ' (сейчас ' + bal + ').' };
      if (amount < 0 && bal + amount < 0) return { error: 'Недостаточно монет для списания (сейчас ' + bal + ').' };
      type = amount > 0 ? 'ADMIN_CREDIT' : 'ADMIN_DEBIT';
      key = 'ADMIN:' + nonce;
    } else {
      let rules = [];
      try { rules = JSON.parse(S.achievement_rules || '[]') || []; } catch (e) { rules = []; }
      const rule = rules.find(function (r) { return String(r.id) === String(p.rule_id || ''); });
      if (!rule) return { error: 'Правило достижения не найдено. Доступные: ' + (rules.map(function (r) { return r.id; }).join(', ') || 'нет правил (задайте achievement_rules в настройках)') };
      amount = parseInt(rule.amount, 10);
      if (!Number.isFinite(amount) || amount <= 0) return { error: 'В правиле указана некорректная сумма.' };
      type = 'ACHIEVEMENT'; reason = 'Достижение: ' + (rule.name || rule.id);
      key = rule.repeatable ? 'ACH:' + rule.id + ':' + nonce : 'ACH:' + rule.id + ':' + emp.employee_id;
    }
    return {
      summary: (amount > 0 ? 'Начислить +' : 'Списать ') + amount + ' Fish Coins сотруднику ' + emp.tuna_id + ' (' + esc(emp.full_name) + '), баланс сейчас ' + bal + '.\nПричина: ' + esc(reason),
      exec: {
        op: 'LEDGER',
        ledger: { employee_id: emp.employee_id, amount: amount, transaction_type: type, reason: reason, initiated_by: 'ADMIN:' + inp.telegram_id, related_shift_id: '', idempotency_key: key },
        ledger_target_telegram: emp.telegram_id,
        audit: { action: op, target_employee_id: emp.employee_id, details: { tuna_id: emp.tuna_id, balance_before: bal, amount: amount, transaction_type: type, reason: reason } },
        notifications: [],
      },
    };
  }
  if (op === 'SET_GEO') {
    const lat = Number(String(p.lat || '').replace(',', '.'));
    const lon = Number(String(p.lon || '').replace(',', '.'));
    const rad = Number(p.radius);
    if (!Number.isFinite(lat) || lat < -90 || lat > 90 || !Number.isFinite(lon) || lon < -180 || lon > 180) return { error: 'Неверные координаты. Формат: /geo 51.161613 71.417481 150' };
    if (!Number.isFinite(rad) || rad < 20 || rad > 5000) return { error: 'Радиус — от 20 до 5000 метров.' };
    const before = { lat: S.work_lat, lon: S.work_lon, radius: S.work_radius_m };
    const after = { lat: String(lat), lon: String(lon), radius: String(Math.round(rad)) };
    return {
      summary: 'Изменить рабочую точку: ' + after.lat + ', ' + after.lon + ', радиус ' + after.radius + ' м (было: ' + before.lat + ', ' + before.lon + ', ' + before.radius + ' м).',
      exec: { op: 'SET_GEO', geo: [{ key: 'work_lat', value: after.lat }, { key: 'work_lon', value: after.lon }, { key: 'work_radius_m', value: after.radius }], audit: { action: op, target_employee_id: '', details: { before: before, after: after } }, notifications: [] },
    };
  }
  if (op === 'RESET_PROFILE') {
    const emp = findEmp(p.tuna_id);
    if (!emp) return { error: 'Активный сотрудник ' + esc(p.tuna_id || '') + ' не найден. Формат: /reset TUNA-000001' };
    return {
      summary: 'Сбросить профиль ' + emp.tuna_id + ' (' + esc(emp.full_name) + '). Сотруднику нужно будет зарегистрироваться заново; история смен и Fish Coins сохранится, приветственный бонус повторно не начисляется.',
      exec: { op: 'RESET_PROFILE', reset: { employee_id: emp.employee_id }, audit: { action: op, target_employee_id: emp.employee_id, details: { tuna_id: emp.tuna_id, before: 'ACTIVE', after: 'RESET' } }, notifications: [{ chat_id: emp.telegram_id, text: 'Ваш профиль TUNA сброшен администратором. Отправьте /start, чтобы пройти регистрацию заново. История смен и Fish Coins сохранена.' }] },
    };
  }
  return { error: 'Неизвестная операция.' };
}

const EMPLOYEE_ACTIONS = ['MY_COINS', 'MY_STATS', 'MY_PROFILE', 'START_VACATION', 'START_SICK', 'START_MEETING'];
const ADMIN_READ = ['ADMIN_MENU', 'LIST_PENDING', 'LIST_EMPLOYEES'];
const ADMIN_MUT = ['APPROVE_REQUEST', 'REJECT_REQUEST', 'ADJUST_COINS', 'GRANT_ACHIEVEMENT', 'SET_GEO', 'RESET_PROFILE'];

// ---------- DIALOG_INPUT ----------
if (action === 'DIALOG_INPUT') {
  const t = inp.text;
  if (t === CANCEL_BTN || t === '/cancel' || t === NO_BTN) {
    R.op = 'CLEAR_DIALOG'; R.result = 'CANCELLED'; reply('Действие отменено.', 'main_menu');
    return done();
  }
  if (!dlg) { R.result = 'NO_DIALOG'; reply('Нет активного действия. Выберите пункт меню.', 'main_menu'); return done(); }
  const exp = DateTime.fromISO(String(dlg.expires_at || ''));
  if (!exp.isValid || exp < now) { R.op = 'CLEAR_DIALOG'; R.result = 'EXPIRED'; reply('Время ожидания истекло, начните заново из меню.', 'main_menu'); return done(); }
  if (dlg.flow === 'ADMIN_CONFIRM') {
    if (t === YES_BTN) action = 'CONFIRM_YES';
    else { R.result = 'AWAIT_CONFIRM'; reply('Подтвердите действие кнопкой.\n\n' + (dlgPayload.summary || ''), 'reply', CONFIRM_KB); return done(); }
  } else if (HR_FLOWS[dlg.flow]) {
    if (!me) { R.op = 'CLEAR_DIALOG'; R.result = 'NOT_REGISTERED'; reply('Вы не зарегистрированы. Отправьте /start.', 'remove'); return done(); }
    const flow = dlg.flow; const step = dlg.step; const p = dlgPayload;
    const r = hrHandle(flow, step, t, p);
    if (r.error) { R.result = 'INVALID_INPUT'; const pr = hrPrompt(flow, step); reply('⚠️ ' + r.error + '\n\n' + pr.text, 'reply', pr.kb); return done(); }
    if (r.next) { setDialog(flow, r.next, p, 30); R.result = 'STEP'; const pr = hrPrompt(flow, r.next); reply(pr.text, 'reply', pr.kb); return done(); }
    const rid = 'REQ-' + uuidv4().replace(/-/g, '').slice(0, 6).toUpperCase();
    const type = HR_FLOWS[flow].type;
    R.op = 'SUBMIT_REQUEST'; R.result = 'SUBMITTED';
    R.request = { request_id: rid, employee_id: me.employee_id, telegram_id: me.telegram_id, request_type: type, start_date: p.start_date || '', end_date: p.end_date || '', comment: p.comment || '', status: 'PENDING', created_ts: nowIso };
    const period = (p.start_date || '') + (p.end_date ? ' — ' + p.end_date : '');
